// Adapter: the rule below is the same JavaScript as the recipe's n8n build.
// $('Step name') answers from this step's inputs: each is that step's output in this scenario.
const SOURCES = {"Config": "in0_Config", "Step 9: Read the brief": "in1_Step9Readthebrief", "Step 9: Read the pause": "in2_Step9Readthepause"};
const LISTS = [];
const EXECUTED = [];
const DATA = {};
for (const [node, key] of Object.entries(SOURCES)) {
  const raw = input[key];
  let v = raw;
  if (typeof raw === 'string') { try { v = JSON.parse(raw); } catch (e) { v = raw; } }
  DATA[node] = LISTS.includes(node) ? (v || []).map(i => (i && i.json !== undefined ? i : { json: i })) : [{ json: v }];
}
const $ = (node) => {
  const ran = node in DATA || EXECUTED.includes(node);
  const list = () => { if (!(node in DATA)) throw new Error(`step ${node} has no data in this scenario`); return DATA[node]; };
  return { isExecuted: ran, first: () => list()[0], last: () => list()[list().length - 1], all: () => list(),
           get item() { return list()[0]; } };
};
const INPUT = "Step 9: Read the pause";
const $input = { all: () => $(INPUT).all(), first: () => $(INPUT).first(), last: () => $(INPUT).last(), get item() { return $(INPUT).first(); } };
const $execution = { id: input.run_id };
// The webhook's fields, as the rule reads them in n8n: $('Step 9: Owner confirms the invoices').first().json.body.
const __list = v => {
  if (typeof v === 'string') { let p; try { p = JSON.parse(v); } catch (e) { p = null; }
    v = p && typeof p === 'object' ? p : v.split(',').map(x => x.trim()).filter(Boolean); }
  if (typeof v === 'number') v = [String(v)];
  const list = Array.isArray(v) ? v : v && typeof v === 'object' ? Object.values(v) : [];
  return list.map(x => (x && typeof x === 'object' ? Object.values(x)[0] : x)); };
DATA["Step 9: Owner confirms the invoices"] = [{ json: { body: { "message_id": input.t_message_id, "invoices": __list(input.t_invoices), "by": input.t_by, "until": input.t_until } } }];
if (Number(input.pause_status) !== 200) DATA['Step 9: Read the pause'] = [];  // no pause read: n8n's output 0 is empty
// n8n's SQL gives one row or an empty item; the table API gives a list of at most one row.
DATA['Step 9: Read the brief'] = DATA['Step 9: Read the brief'].map(i => ({ json: Array.isArray(i.json) ? (i.json[0] || {}) : (i.json || {}) }));
const BODIES = (out) => ({"id_q": out.refused ? '' : encodeURIComponent(out.id), "pause_body": out.refused ? null : JSON.stringify({ id: out.id, invoice: out.invoice, account: out.account, status: 'open', kind: out.kind, set_by: out.by, why: 'reply ' + out.message_id + ', confirmed by the owner', message_id: out.message_id, until: out.until }), "narrow_body": out.refused ? null : JSON.stringify({ status: 'narrowed', narrowed_by: out.by, narrowed_at: new Date().toISOString(), covers: out.invoices }), "narrowed_log": out.refused ? null : JSON.stringify({ recipe: 'R8.3', item: out.message_id, decision: 'pause narrowed to ' + out.invoices.join(', '), rules: { by: out.by, invoices: out.invoices, kind: out.kind, until: out.until } }), "not_narrowed_log": JSON.stringify({ recipe: 'R8.3', item: String($('Step 9: Owner confirms the invoices').first().json.body.message_id), decision: 'pause not narrowed: ' + out.reason, rules: { by: $('Step 9: Owner confirms the invoices').first().json.body.by || null } }), "failed_body": JSON.stringify({ recipe: 'R8.3', item: String($('Step 9: Owner confirms the invoices').first().json.body.message_id), reason: 'write failed', detail: 'Narrowing the pause failed; the whole-account pause stays until it is fixed', owner: $('Config').first().json.ar_lead })});
const one = (r) => (Array.isArray(r) ? r : [r]).filter(Boolean).map(i => (i.json !== undefined ? i.json : i));
const $json = INPUT && INPUT in DATA ? $input.first().json : {};
const __rule = () => {
// Step 9: only a briefed reply with its whole-account pause still open narrows, to the invoices the owner names.
const b = $('Step 9: Owner confirms the invoices').first().json.body;
const brief = $('Step 9: Read the brief').first().json;
const p = $('Step 9: Read the pause').all(0);
const pause = p.length ? p[0].json : null;
const invoices = Array.isArray(b.invoices) ? b.invoices.map(String).filter(Boolean) : [];
const refuse = reason => [{ json: { refused: true, reason }, pairedItem: 0 }];
if (!brief || !brief.decision) return refuse('no brief for this message');
if (!pause || pause.status !== 'open') return refuse('no open whole-account pause');
if (!invoices.length) return refuse('no invoices confirmed');
return invoices.map(n => ({ json: { refused: false, id: n + '-' + b.message_id, invoice: n, account: pause.account,
  kind: brief.category, message_id: b.message_id, by: b.by || null, until: b.until || null, invoices }, pairedItem: 0 }));
};
return { items: one(__rule()).map(o => Object.assign({}, o, BODIES(o))) };

